INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷81·晋少帝本纪·天福八年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0492098592de640119d51b379b17908f65b59b0/content/books/zizhi-tongjian/vol-283/year-0943/part-02/sources/library/jiuwudaishi-081-943-march/source.txt", "note": "《旧五代史》卷81·晋少帝本纪·天福八年三月，段落 jiu-wudaishi-205deb4a7860-p001987；已核上下文及传主，纸本及异文待核。", "id": "89d1a8a0-7cad-56c0-9a87-cf96944dc270"}, {"title": "资治通鉴·卷283·天福八年·四五月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0492098592de640119d51b379b17908f65b59b0/content/books/zizhi-tongjian/vol-283/year-0943/part-02/sources/library/tongjian-283-943-april-may/source.txt", "note": "《资治通鉴》卷283·天福八年·四五月及追述，段落 zizhi-tongjian-a63549944a71-p003367；已核上下文及传主，纸本及异文待核。", "id": "8e1284b2-bd81-5ec3-9d02-501f6839c4d0"}, {"title": "资治通鉴·卷283·天福八年·南汉继位", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0492098592de640119d51b379b17908f65b59b0/content/books/zizhi-tongjian/vol-283/year-0943/part-02/sources/library/tongjian-283-943-south-han/source.txt", "note": "《资治通鉴》卷283·天福八年·南汉继位，段落 zizhi-tongjian-a63549944a71-p003366；已核上下文及传主，纸本及异文待核。", "id": "6a3fff2a-917e-5fa3-846f-bbe6dff651f3"}, {"title": "新五代史·卷65·南汉世家·刘玢被杀", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0492098592de640119d51b379b17908f65b59b0/content/books/zizhi-tongjian/vol-283/year-0943/part-02/sources/library/xinwudaishi-065-liu-bin-death/source.txt", "note": "《新五代史》卷65·南汉世家·刘玢被杀，段落 xin-wudaishi-b08f244b9241-p003280；已核上下文及传主，纸本及异文待核。", "id": "046bd0e9-df92-529e-994d-b1342758770f"}, {"title": "新五代史·卷65·南汉世家·刘晟继位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0492098592de640119d51b379b17908f65b59b0/content/books/zizhi-tongjian/vol-283/year-0943/part-02/sources/library/xinwudaishi-065-liu-sheng-accession/source.txt", "note": "《新五代史》卷65·南汉世家·刘晟继位，段落 xin-wudaishi-b08f244b9241-p003281；已核上下文及传主，纸本及异文待核。", "id": "ac3719db-7597-59f3-ad72-ea42a782a2d1"}, {"title": "资治通鉴·卷283·后晋天福八年·二月至四月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/tongjian-283-943-early-b/source.txt", "note": "《资治通鉴》卷283·后晋天福八年·二月至四月及追述，段落 zizhi-tongjian-a63549944a71-p003365；已核上下文及传主，纸本及异文待核。", "id": "59a0598f-12f2-5d08-89c9-b6804ccea94a"}, {"title": "新五代史·卷9·晋出帝本纪·天福八年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-009-943-return/source.txt", "note": "《新五代史》卷9·晋出帝本纪·天福八年，段落 xin-wudaishi-b08f244b9241-p000334；已核上下文及传主，纸本及异文待核。", "id": "8b6277d6-bc14-525d-a7c0-ae15a89bdca9"}, {"title": "新五代史·卷62·南唐世家·李璟与诸弟", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-062-jing-brothers/source.txt", "note": "《新五代史》卷62·南唐世家·李璟与诸弟，段落 xin-wudaishi-b08f244b9241-p003137；已核上下文及传主，纸本及异文待核。", "id": "4eec6cb7-f426-58dc-9677-661a25ec2fce"}, {"title": "新五代史·卷62·南唐世家·冯延巳等", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-062-feng-name/source.txt", "note": "《新五代史》卷62·南唐世家·冯延巳等，段落 xin-wudaishi-b08f244b9241-p003139；已核上下文及传主，纸本及异文待核。", "id": "819d41cd-204a-5095-8cdb-49e78419f252"}, {"title": "新五代史·卷68·闽世家·王延羲妻李氏", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7e9f7a7ea4b22cbbe6d05277dd5c16ed51a9e06/content/books/zizhi-tongjian/vol-283/year-0942/part-01/sources/library/xinwudaishi-068-min-li-empress/source.txt", "note": "《新五代史》卷68·闽世家·王延羲妻李氏，段落 xin-wudaishi-b08f244b9241-p003411；已核上下文及传主，纸本及异文待核。", "id": "f65572e7-91e0-5d18-a84c-68aa6429f9d4"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "赵莹", "aliases": ["趙瑩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵莹，劝赴任者。", "biography": null, "status": "draft", "id": "1f5a50e7-b046-593f-8be4-621934211b27"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "韩熙载", "aliases": ["韓熙載", "熙载"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：韩熙载，韩叔嗣之子、拟奔吴者。", "biography": null, "status": "draft", "id": "83af8c00-ec9d-5693-9e26-56dc1a5a6a88"}, {"name": "宋氏（南唐李昪后）", "aliases": ["宋氏（李昪后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昪的皇后。937年被立为皇后，939年与李昪为李氏父母服丧。个人名字及生卒年本次未核。", "biography": null, "status": "draft", "id": "87d8df9d-227e-5ea6-9284-514b5a1aebcd"}, {"name": "钟氏（李璟妻）", "aliases": ["鍾氏（李璟妻）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：钟氏（李璟妻）。", "biography": null, "status": "draft", "id": "f2385a50-e9fa-5f2d-9f1e-90cc387c61fb"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "李建勋", "aliases": ["李建勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李建勋，节度副使、屡陈功业者。", "biography": null, "status": "draft", "id": "6b23676b-32be-5201-8ad3-171b7cc648e3"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "周宗", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：周宗。", "biography": null, "status": "draft", "id": "155e76cd-ab0e-5e2a-a791-43d64ebe4669"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "常梦锡", "aliases": ["常夢錫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，万年人。941年四月与陈觉一起被李昪任命为宣徽副使。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "9eaabd48-0b3a-5cc3-a5ec-f9107c987328"}, {"name": "王彦俦", "aliases": ["王彥儔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上蔡人，南唐池州节度使。史书说他对当地贬官管束过严，但尊重被贬为池州判官的常梦锡。具体年月和生卒年尚未核。", "biography": null, "status": "draft", "id": "89e632ad-68bd-5ff9-b413-506e1e03f147"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "查文徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "休宁人，南唐官员。943年李璟即位后，史书记他与陈觉、冯延巳、冯延鲁、魏岑互相引荐，不久与魏岑同任枢密副使。当时五人被称为五鬼，称呼按史书记载保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "b0abcb8a-3aa7-5d58-8f3c-79f4fc15b117"}, {"name": "杜昌业", "aliases": ["杜昌業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐江州观察使。943年冯延鲁升中书舍人、勤政殿学士后，他批评仅因言语合意便授高官会使日后功臣难以获得适当奖赏。生卒年尚未核。", "biography": null, "status": "draft", "id": "c4dbe076-e0c1-54df-a3e4-875c08c1fec6"}, {"name": "刘弘度", "aliases": ["劉弘度", "刘洪度", "劉洪度"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘度，获封王爵之子。", "biography": null, "status": "draft", "id": "9f834996-df40-5434-9360-acbf54bfe3c6"}, {"name": "刘弘昌", "aliases": ["劉弘昌", "刘洪昌", "劉洪昌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘昌，获封王爵之子。", "biography": null, "status": "draft", "id": "fda27388-00bf-5390-90ae-9604e2ec1c33"}, {"name": "吴怀恩", "aliases": ["吳懷恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "番禺人，南汉内常侍。刘弘度即位后，他与越王刘弘昌多次劝谏，刘弘度没有听从。具体劝谏年月和生卒年未载。", "biography": null, "status": "draft", "id": "10645068-7e2a-59d2-8714-eb605c240fb1"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "陈道庠", "aliases": ["陳道庠", "陈道痒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉指挥使，端州人。942年钱帛馆之战中救出被围的刘弘昌、刘弘杲。主书前处写陈道痒，同段籍贯句及新五代史写陈道庠，姓名据此校读，原文不改。", "biography": null, "status": "draft", "id": "8c0e66da-c540-5719-8bf2-606db592f4bf"}, {"name": "刘思潮", "aliases": ["劉思潮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士。943年在刘弘熙安排下，由陈道庠召入晋王府练习手搏；随后参与杀死刘弘度，刘弘熙即位后受到赏赐。《新五代史》还记刘思潮等获封功臣。生卒年尚未核。", "biography": null, "status": "draft", "id": "d7493fd7-d448-5c67-8a8d-eb273df31b0a"}, {"name": "谭令禋", "aliases": ["譚令禋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士，943年在刘弘熙安排下，由陈道庠召入晋王府练习手搏。史书将他列于五名力士中；陈道庠、刘思潮等随后杀死刘弘度，但本段没有逐一说明所有力士当时的动作。生卒年尚未核。", "biography": null, "status": "draft", "id": "0e89825f-b852-5c2e-a140-9238c42a0625"}, {"name": "林少强", "aliases": ["林少強", "林少彊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士，943年与刘思潮等在晋王府练习手搏。《资治通鉴》作林少强，《新五代史》作林少彊。与林少良同姓名相近，但本段未明确亲属关系，暂不建兄弟关系。生卒年尚未核。", "biography": null, "status": "draft", "id": "9f17dd1c-9ee9-595e-a653-d5395d3ee4d8"}, {"name": "林少良", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士，943年与刘思潮等在晋王府练习手搏。与林少强同姓名相近，但本段未明确亲属关系，暂不建兄弟关系。生卒年尚未核。", "biography": null, "status": "draft", "id": "ad7835a8-e59d-5074-8319-bb08ffa95cda"}, {"name": "何昌廷", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士，943年在刘弘熙安排下，由陈道庠召入晋王府练习手搏。史书将他列于五名力士中，本段未逐一说明他在杀死刘弘度时的动作。生卒年尚未核。", "biography": null, "status": "draft", "id": "5b94ec77-7dd9-5980-b1b2-596ce866c6d3"}, {"name": "刘弘杲", "aliases": ["劉弘杲", "刘洪杲", "劉洪杲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘杲，获封王爵之子。", "biography": null, "status": "draft", "id": "eb7c29f2-2022-5446-97aa-43b3b6d75ad8"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "尚氏（王延羲贤妃）", "aliases": ["尚氏", "尚氏（王延羲妃）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "尚保殷的女儿，王延羲的贤妃。943年条下记王延羲纳她、立为贤妃；史书称她受宠，王延羲醉中依她的意思杀人或赦免。具体日期、个人名字和生卒年尚未核。", "biography": null, "status": "draft", "id": "1c7299f5-4b3f-52e5-bb38-eabe0fe5951d"}, {"name": "尚保殷", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国金吾使，尚氏的父亲。943年条下记王延羲纳其女并立为贤妃。具体日期和生卒年尚未核。", "biography": null, "status": "draft", "id": "b0dc4086-ac66-52d6-8265-45b649b12f60"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

